from lib import *
chapter(6,'science','living-creatures-exploring-their-characteristics','Living Creatures: Exploring their Characteristics',
 ('Seed or stone?','A seed and a small stone look alike. Plant both in soil with water. After a week the seed sprouts. The stone does not. What makes something alive?'),
 [('What sets the living apart',['Living things share certain characteristics. They need food, they breathe, they grow, they respond to changes, they reproduce and they die.','A stone or a toy does not show these characteristics, so it is non-living.']),
  ('Needs of living things',['Living things need food, water, air and a place to live (habitat).','Plants make their own food using sunlight. Animals get food by eating plants or other animals.']),
  ('Germination and growth in plants',['A seed needs water, air and a suitable temperature to germinate, which means to sprout.','The root grows down and the shoot grows up, and the plant grows bigger over time.','Plants respond to light, and many plant parts grow toward it. Touch-me-not leaves fold when touched.']),
  ('Life cycles',['A plant\'s life cycle goes from seed to seedling to plant to flower to fruit with seeds.','Many animals change form as they grow. A butterfly goes from egg to caterpillar to pupa to butterfly. A frog goes from egg to tadpole to frog.','A mosquito goes from egg to larva to pupa to adult, and these early stages live in water.']),
  ('Responding and reproducing',['Living things respond to stimuli like light, sound, touch and temperature.','They reproduce to make more of their kind and all living things eventually die.'])],
 [('Is a candle flame living?',[('It uses oxygen and gives heat, but does it grow, respond and reproduce?','Check each characteristic.'),('It does not, so a flame is not living.','Not alive.')])],
 ('Explain how you would prove that a seed is living.',['Plant it with water and air.','It germinates and grows.'],['Thinking moving things are always living.','Thinking a plant does not respond.']),
 ['Living things need food, breathe, grow, respond, reproduce and die.','Seeds need water, air and warmth to germinate.','Life cycles can include big changes in form.'],
 [mcq('c10-1',1,'Which is a characteristic of living things?','They grow',[('They float','Many non-living things float.'),('They are heavy','Weight does not decide this.')],'Growth is a sign of life.'),
  mcq('c10-2',1,'A seed sprouting is called','germination',[('evaporation','This relates to water.'),('digestion','This relates to food.')],'It begins growth.'),
  tf('c10-3',1,'A stone grows and reproduces.',False,'A stone is non-living.'),
  mcq('c10-4',1,'A frog starts life as','an egg and then a tadpole',[('an adult','It has stages.'),('a pupa','Frogs do not have a pupa.')],'It changes form.'),
  mcq('c10-5',2,'A seed needs for germination','water, air and warmth',[('only light','Many seeds germinate in dark soil.'),('only soil','Soil is not required for germination itself.')],'These are the basic needs.'),
  mcq('c10-6',2,'The butterfly stages are','egg, caterpillar, pupa, adult',[('egg, adult','Stages are missing.'),('egg, tadpole','Tadpole is for frogs.')],'Complete change.'),
  tf('c10-7',2,'Plants respond to light.',True,'They bend towards light.'),
  mcq('c10-8',2,'Mosquito larvae live in','water',[('soil','Eggs are laid on water.'),('air','Larvae live in water.')],'Stagnant water spreads mosquitoes.'),
  mcq('c10-9',3,'Responding to the environment is called responding to','stimuli',[('germs','Germs are microbes.'),('seeds','Seeds are not a stimulus.')],'Light, sound, touch.'),
  mcq('c10-10',3,'Non-living things','do not grow or reproduce',[('breathe','Non-living things do not breathe.'),('need food','They do not eat.')],'They lack characteristics of life.')],
 keep=['germination','habitat','life cycle'])
chapter(6,'science','natures-treasures','Nature\'s Treasures',
 ('A glass of water','You drink water, breathe air and eat food that grew in soil. All came from nature. These gifts are called natural resources, and we must use them wisely.'),
 [('Natural resources',['A natural resource is something from nature that we use, such as air, water, soil, sunlight, forests, minerals and fossil fuels.','Renewable resources can be replaced, like sunlight, wind and water if used properly.','Non-renewable resources are limited and take millions of years to form, such as coal, petroleum and natural gas.']),
  ('Air, water and sun',['Air gives oxygen for breathing and moves as wind.','Water is needed for drinking, farming and industry. Only a small part of Earth\'s water is fresh and easy to use.','The Sun gives light and heat, and we can use solar energy for heating and electricity.']),
  ('Forests',['Forests give wood, food, medicines and homes for animals. They clean the air and prevent soil erosion.']),
  ('Soil, rocks and minerals',['Soil is formed from rocks broken down over thousands of years and has layers: topsoil, subsoil and bedrock.','Topsoil is rich in humus and supports plants.','Minerals, such as iron and coal, are dug out of mines.']),
  ('Fossil fuels',['Coal, petroleum and natural gas formed from remains of plants and animals buried millions of years ago.','Burning them gives energy but causes pollution.']),
  ('Use wisely',['Reduce, reuse and recycle. Save water, switch off lights, plant trees and use public transport.'])],
 [('Why should we save petrol?',[('It is a fossil fuel and takes millions of years to form.','Non-renewable.'),('Once used up it cannot be replaced soon.','Save.')])],
 ('Explain the difference between renewable and non-renewable resources.',['Renewable can be replaced.','Non-renewable are limited.'],['Thinking water is infinite.','Thinking only humans need forests.']),
 ['Natural resources come from nature.','Renewable and non-renewable resources differ in how fast they are replaced.','Forests, soil and water are precious.','Reduce, reuse and recycle.'],
 [mcq('r11-1',1,'Which is renewable?','Sunlight',[('Coal','It takes millions of years to form.'),('Petroleum','It is a fossil fuel.')],'The Sun keeps shining.'),
  mcq('r11-2',1,'Coal is a','fossil fuel',[('metal','Coal is not a metal.'),('mineral water','No.')],'It formed from buried plants.'),
  tf('r11-3',1,'Forests clean the air.',True,'Trees take in carbon dioxide and give oxygen.'),
  mcq('r11-4',1,'The top layer of soil is','topsoil',[('bedrock','This is the bottom layer.'),('subsoil','This lies below topsoil.')],'Rich in humus.'),
  mcq('r11-5',2,'Which is non-renewable?','Natural gas',[('Wind','Wind is renewable.'),('Sunlight','Sunlight is renewable.')],'Limited and slow to form.'),
  mcq('r11-6',2,'Soil is formed from','broken rocks',[('plastic','Plastic is man-made.'),('metals only','Soil comes from rocks.')],'Weathering over a long time.'),
  mcq('r11-7',2,'The 3 Rs are','reduce, reuse, recycle',[('run, rest, repeat','Not the 3 Rs.'),('read, write, repeat','Not the 3 Rs.')],'They protect resources.'),
  tf('r11-8',2,'Fresh water is unlimited.',False,'Only a small part of Earth\'s water is fresh.'),
  mcq('r11-9',3,'Burning fossil fuels causes','air pollution',[('more forests','It does not grow forests.'),('clean water','It does not clean water.')],'It releases smoke and gases.'),
  mcq('r11-10',3,'A way to save water','close the tap when not in use',[('leave the tap running','This wastes water.'),('wash the car daily','Uses too much water.')],'Small habits matter.')],
 keep=['renewable','non-renewable','fossil fuel'])
chapter(6,'science','beyond-earth','Beyond Earth',
 ('The night sky','On a clear night we see thousands of stars. Some form patterns. Some wander across the sky. What are they and how far do they go? Let us look beyond Earth.'),
 [('Stars and constellations',['Stars are huge balls of hot gas that give out their own light. The Sun is a star, the nearest one to us.','Stars look tiny because they are very far away.','Groups of stars seen in patterns are called constellations, like Ursa Major (the Great Bear) with the Saptarishi, and Orion.','The Pole Star appears nearly fixed in the north, and ancient sailors used it to find north.']),
  ('Night sky watching',['The stars seem to move across the sky because Earth spins, not because they move around us.','Planets look like bright stars but do not twinkle much. They shine by reflecting sunlight.']),
  ('Our solar system',['The solar system is the Sun with the planets and other objects that go around it.','The eight planets in order from the Sun are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune.','The four inner planets are rocky. Jupiter and Saturn are giants of gas. Moons orbit planets, and Earth has one Moon.','There are also dwarf planets, asteroids and comets.']),
  ('Milky Way and the universe',['Our solar system is part of a huge galaxy of stars called the Milky Way.','There are billions of galaxies in the universe, and the universe is vast beyond imagination.'])],
 [('Which planet is third from the Sun?',[('Order is Mercury, Venus, Earth.','List the planets.'),('Earth is third.','Where we live.')])],
 ('Explain why the Sun looks bigger than other stars.',['It is the nearest star.','Other stars are very much farther away.'],['Thinking planets make their own light.','Thinking the Moon is a star.']),
 ['Stars make their own light.','Constellations are star patterns.','There are eight planets in the solar system.','The Milky Way is our galaxy.'],
 [mcq('b12-1',1,'The nearest star to Earth is','the Sun',[('the Moon','The Moon is not a star.'),('the Pole Star','Much farther away.')],'It is the centre of our solar system.'),
  mcq('b12-2',1,'The number of planets in the solar system is','8',[('9','Only eight in the current count.'),('7','There are eight.')],'Mercury to Neptune.'),
  tf('b12-3',1,'Planets shine by their own light.',False,'They reflect sunlight.'),
  mcq('b12-4',1,'Our galaxy is the','Milky Way',[('Orion','Orion is a constellation.'),('Andromeda','A neighbouring galaxy.')],'We live in the Milky Way.'),
  mcq('b12-5',2,'A group of stars forming a pattern is a','constellation',[('planet','A planet orbits a star.'),('comet','A comet has a tail.')],'Like Orion.'),
  mcq('b12-6',2,'Which planet is the largest?','Jupiter',[('Earth','Earth is much smaller.'),('Mars','Mars is small.')],'A gas giant.'),
  mcq('b12-7',2,'The Pole Star shows','north',[('south','It points north.'),('east','Not east.')],'Used for navigation.'),
  tf('b12-8',2,'The stars move around Earth each night.',False,'It looks so because the Earth spins.'),
  mcq('b12-9',3,'The planet nearest the Sun is','Mercury',[('Venus','Venus is second.'),('Earth','Earth is third.')],'First in order.'),
  mcq('b12-10',3,'Why do stars look small?','They are very far away',[('They are tiny','Many are bigger than the Sun.'),('They are cold','Stars are very hot.')],'Distance makes them look small.')],
 keep=['star','constellation','solar system'])
